UPDATE sqlite_master SET type = 'table', name = 'project', tbl_name = 'project', rootpage = 2, sql = 'CREATE TABLE "project" ("id" INTEGER NOT NULL PRIMARY KEY, "name" VARCHAR(100) NOT NULL, "description" VARCHAR(255), "sum" INTEGER, "charts" INTEGER NOT NULL, "pinned_opened" INTEGER NOT NULL, "hidden_opened" INTEGER NOT NULL, "more" VARCHAR(255), "version" VARCHAR(30) NOT NULL, "create_time" VARCHAR(30) NOT NULL, "update_time" VARCHAR(30) NOT NULL)' WHERE rowid = 1;
