UPDATE sqlite_master SET type = 'table', name = 'experiment', tbl_name = 'experiment', rootpage = 4, sql = 'CREATE TABLE "experiment" ("id" INTEGER NOT NULL PRIMARY KEY, "project_id" INTEGER NOT NULL, "run_id" TEXT NOT NULL, "name" VARCHAR(100) NOT NULL, "description" VARCHAR(255), "sort" INTEGER NOT NULL, "status" INTEGER NOT NULL, "show" INTEGER NOT NULL, "light" VARCHAR(20), "dark" VARCHAR(20), "pinned_opened" INTEGER NOT NULL, "hidden_opened" INTEGER NOT NULL, "more" TEXT, "version" VARCHAR(30) NOT NULL, "create_time" VARCHAR(30) NOT NULL, "finish_time" VARCHAR(30), "update_time" VARCHAR(30) NOT NULL, FOREIGN KEY ("project_id") REFERENCES "project" ("id") ON DELETE CASCADE ON UPDATE CASCADE, CHECK (sort >= 0))' WHERE rowid = 3;
