UPDATE sqlite_master SET type = 'table', name = 'chart', tbl_name = 'chart', rootpage = 9, sql = 'CREATE TABLE "chart" ("id" INTEGER NOT NULL PRIMARY KEY, "experiment_id" INTEGER, "project_id" INTEGER, "name" VARCHAR(100) NOT NULL, "description" VARCHAR(255), "system" INTEGER NOT NULL, "type" VARCHAR(10) NOT NULL, "reference" VARCHAR(10) NOT NULL, "status" INTEGER NOT NULL, "sort" INTEGER, "config" TEXT, "more" TEXT, "create_time" VARCHAR(30) NOT NULL, "update_time" VARCHAR(30) NOT NULL, FOREIGN KEY ("experiment_id") REFERENCES "experiment" ("id") ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY ("project_id") REFERENCES "project" ("id") ON DELETE CASCADE ON UPDATE CASCADE, CHECK ((project_id IS NULL AND experiment_id IS NOT NULL) OR (project_id IS NOT NULL AND experiment_id IS NULL)))' WHERE rowid = 8;
